<script>
    const swapBtn = document.getElementById('swapBtn');
    const fromInput = document.getElementById('flight_from');
    const toInput = document.getElementById('flight_to');
    const fromBadge = document.getElementById('fromBadge');
    const toBadge = document.getElementById('toBadge');

    // --- 1. THE BADGE LOGIC ---
    function updateBadgeFromInput(inputElement, badgeElement) {
        const val = inputElement.value;
        // Checks for ""MIA - Miami"" or ""Miami (MIA)""
        const match = val.match(/^([A-Z]{3})[ -]/) || val.match(/\(([A-Z]{3})\)/);

        if (match) {
            badgeElement.textContent = match[1];
            badgeElement.style.display = 'inline-block';
        } else {
            badgeElement.textContent = """";
            // Op");
            WriteLiteral(@"tional: Hide badge if no code found
            // badgeElement.style.display = 'none';
        }
    }

    // --- 2. THE WATCHDOG (The new ""Different Way"") ---
    // Instead of trusting click events, we track the last known value.
    let lastFromVal = fromInput.value;
    let lastToVal = toInput.value;

    setInterval(() => {
        // Check ""From"" Input
        if (fromInput.value !== lastFromVal) {
            lastFromVal = fromInput.value;       // Update memory
            updateBadgeFromInput(fromInput, fromBadge); // Update UI
        }

        // Check ""To"" Input
        if (toInput.value !== lastToVal) {
            lastToVal = toInput.value;           // Update memory
            updateBadgeFromInput(toInput, toBadge);     // Update UI
        }
    }, 200); // Runs every 200ms (very fast, no performance impact)

    // --- 3. SWAP LOGIC ---
    let isRotated = false;
    swapBtn.addEventListener('click', () => {
        // Swap Values
        const tempValue = from");
            WriteLiteral(@"Input.value;
        fromInput.value = toInput.value;
        toInput.value = tempValue;

        // Swap Badges
        const tempBadge = fromBadge.textContent;
        fromBadge.textContent = toBadge.textContent;
        toBadge.textContent = tempBadge;

        // Animation
        swapBtn.style.transform = isRotated ?
            ""translate(-50%, -50%) rotate(0deg)"" :
            ""translate(-50%, -50%) rotate(180deg)"";
        isRotated = !isRotated;

        // Update our Watchdog variables immediately so it doesn't double-trigger
        lastFromVal = fromInput.value;
        lastToVal = toInput.value;
    });
</script>

