<script>
    document.addEventListener(""DOMContentLoaded"", () => {
        // Configuration
        const scrollSpeed = 0.8; // Lower is slower, higher is faster

        function initInfiniteScroll(selector, direction) {
            const column = document.querySelector(selector);
            if (!column) return;

            // 1. Clone content for the infinite loop effect
            const originalContent = column.innerHTML;
            column.innerHTML = originalContent + originalContent;

            let scrollPos = 0;
            let isPaused = false;

            // Calculate the point where we need to reset the loop
            const halfHeight = ");
            WriteLiteral(@"column.scrollHeight / 2;

            // 2. Pause Logic
            column.addEventListener('mouseenter', () => isPaused = true);
            column.addEventListener('mouseleave', () => isPaused = false);

            function animate() {
                if (!isPaused) {
                    if (direction === 'up') {
                        scrollPos -= scrollSpeed;
                        // Reset when the first half has scrolled away
                        if (Math.abs(scrollPos) >= halfHeight) {
                            scrollPos = 0;
                        }
                    } else {
                        scrollPos += scrollSpeed;
                        // Reset when it hits the bottom
                        if (scrollPos >= 0) {
                            scrollPos = -halfHeight;
                        }
                    }
                    column.style.transform = `translateY(${scrollPos}px)`;
                }

                // Keeps the animation running smo");
            WriteLiteral(@"othly
                requestAnimationFrame(animate);
            }

            // Set initial position for the downward column
            if (direction === 'down') {
                scrollPos = -halfHeight;
            }

            animate();
        }

        // Initialize the logic for your specific classes
        initInfiniteScroll('.scroll-up', 'up');
        initInfiniteScroll('.scroll-down', 'down');
    });
</script>

